import 'package:flutter/material.dart'; import 'logbook_ui.dart';
class SecondaryButton extends StatelessWidget { const SecondaryButton({super.key,required this.label,required this.onPressed, this.icon}); final String label; final VoidCallback? onPressed; final IconData? icon; @override Widget build(BuildContext context)=>OutlinedButton.icon(onPressed:onPressed,icon:icon==null?const SizedBox.shrink():Icon(icon),label:Text(label),style:OutlinedButton.styleFrom(foregroundColor:logbookPrimary,minimumSize:const Size.fromHeight(52),side:const BorderSide(color:logbookPrimary),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(16)))); }
